<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class MartyrFilters {
    public static function galleryInput(array $input):array {
        return array_intersect_key($input,array_flip(['q','axis','date_kind','calendar','year_from','year_to','p','geo_role','geo_country','geo_province','geo_county','geo_city']));
    }
    public static function conditions(PDO $db,array $f):array {
        if(!MartyrTaxonomySchema::ready($db))return ['',[]];$parts=[];$args=[];$input=$f['axis']??[];if(!is_array($input)||count($input)>30)throw new HttpError(422,'فیلتر محورها معتبر نیست.');$axes=[];foreach(MartyrCatalog::axes($db,true) as $a)$axes[$a['axis_key']]=$a;
        foreach($input as $axis=>$values){if(!isset($axes[$axis]))throw new HttpError(422,'این محور برای فیلتر عمومی فعال نیست.');$values=is_array($values)?$values:[$values];$values=array_values(array_filter($values,fn($v)=>$v!==''));if(count($values)>50||($axes[$axis]['selection_mode']==='single'&&count($values)>1))throw new HttpError(422,'تعداد گزینه‌های فیلتر با محور سازگار نیست.');if(!$values)continue;$ids=[];foreach($values as $v){if(!is_string($v)&&!is_int($v)||!ctype_digit((string)$v))throw new HttpError(422,'شناسه فیلتر معتبر نیست.');$term=Db::query($db,'SELECT id,taxonomy FROM protocol_terms WHERE id=?',[(int)$v])->fetch();$canonical=MartyrCatalog::canonical($db,(int)$v);if(!$term||$term['taxonomy']!==$axis||!Db::query($db,'SELECT id FROM protocol_terms WHERE id=? AND active=1',[$canonical])->fetchColumn())throw new HttpError(422,'مقدار فیلتر فعال نیست.');$ids=[...$ids,...MartyrCatalog::family($db,(int)$v)];if($axes[$axis]['hierarchical']){$queue=[$canonical];$seen=[];while($queue){$parent=array_shift($queue);if(isset($seen[$parent]))continue;$seen[$parent]=true;foreach(Db::query($db,'SELECT id FROM protocol_terms WHERE taxonomy=? AND parent_id=?',[$axis,$parent])->fetchAll(PDO::FETCH_COLUMN) as $child){$queue[]=(int)$child;$ids=[...$ids,...MartyrCatalog::family($db,(int)$child)];}if(count($seen)>5000)throw new HttpError(422,'دامنه سلسله‌مراتب فیلتر بیش از حد است.');}}}$ids=array_values(array_unique($ids));$parts[]='EXISTS(SELECT 1 FROM martyr_public_terms mf WHERE mf.martyr_id=m.id AND mf.axis_key=? AND mf.term_id IN ('.implode(',',array_fill(0,count($ids),'?')).'))';$args=[...$args,$axis,...$ids];}
        $geo=[];foreach(['country','province','county','city'] as $level){$raw=$f['geo_'.$level]??'';if($raw==='')continue;if(!is_scalar($raw)||!ctype_digit((string)$raw))throw new HttpError(422,'شناسه مکان معتبر نیست.');$term=Db::query($db,'SELECT id FROM protocol_terms WHERE id=? AND taxonomy=? AND active=1',[(int)$raw,$level])->fetchColumn();if(!$term)throw new HttpError(422,'مکان فعال پیدا نشد.');$geo[$level.'_id']=(int)$raw;}
        if($geo||($f['geo_role']??'')!==''){$role=$f['geo_role']??'residence_at_incident';if(!in_array($role,['birth_place','residence_at_incident','martyrdom_place','burial_place'],true))throw new HttpError(422,'نوع محل معتبر نیست.');$sql='EXISTS(SELECT 1 FROM martyr_public_facts gf WHERE gf.martyr_id=m.id AND gf.fact_key=?';$args[]=$role;$sql.=' AND (gf.country_id IS NOT NULL OR gf.province_id IS NOT NULL OR gf.county_id IS NOT NULL OR gf.city_id IS NOT NULL)';foreach($geo as $col=>$id){$sql.=' AND gf.'.$col.'=?';$args[]=$id;}$parts[]=$sql.')';}
        $from=Security::normalize(Security::text($f,'year_from',4,false));$to=Security::normalize(Security::text($f,'year_to',4,false));if($from!==''||$to!==''){$key=$f['date_kind']??'martyrdom_date';$cal=$f['calendar']??'jalali';if(!in_array($key,['birth_date','martyrdom_date'],true)||!in_array($cal,['jalali','gregorian','hijri'],true)||($from!==''&&(!ctype_digit($from)||(int)$from<1))||($to!==''&&(!ctype_digit($to)||(int)$to<1))||($from!==''&&$to!==''&&(int)$from>(int)$to))throw new HttpError(422,'بازه سال و تقویم معتبر نیست.');$sql='EXISTS(SELECT 1 FROM martyr_public_facts df WHERE df.martyr_id=m.id AND df.fact_key=? AND df.calendar=?';$args[]=$key;$args[]=$cal;if($from!==''){$sql.=' AND df.year>=?';$args[]=(int)$from;}if($to!==''){$sql.=' AND df.year<=?';$args[]=(int)$to;}$parts[]=$sql.')';}
        return [implode(' AND ',$parts),$args];
    }
    public static function options(PDO $db,array $f=[]):array {return GalleryFacets::options($db,$f);}
}
